def divide(a: int, b: int) -> float:
    try:
        return a / b
    except ZeroDivisionError:
        return 0.0

result = divide(10, 0)
print(result)

rust_code:
fn divide(a: i32, b: i32) -> Result<f64, String> {
    if b == 0 {
        Err("Division by zero".to_string())
    } else {
        Ok(a as f64 / b as f64)
    }
}

fn main() {
    match divide(10, 0) {
        Ok(result) => println!("Result: {}", result),
        Err(e) => println!("Error: {}", e),
    }
}
